definition.script:
pipeline {
    agent any

    tools {
        maven 'maven3.9'
        jdk 'jdk17'
    }

    parameters {
        string(
            name: 'BRANCH_NAME',
            defaultValue: 'main',
            description: 'Git branch to build'
        )

        booleanParam(
            name: 'RUN_TESTS',
            defaultValue: true,
            description: 'Run test cases?'
        )

        choice(
            name: 'BUILD_TYPE',
            choices: ['debug', 'release'],
            description: 'Choose the build type'
        )
    }

    stages {
        stage('Git Checkout') {
            steps {
                git branch: params.BRANCH_NAME,
                    url: 'https://github.com/sandhya-en/Boardgame.git'
            }
        }

        stage('Compile') {
            steps {
                echo 'Compiling the project'
                sh 'mvn compile'
            }
        }

        stage('Test') {
            when {
                expression {
                    return params.RUN_TESTS
                }
            }
            steps {
                echo 'Running test cases'
                sh 'mvn test'
            }
        }

        stage('Build') {
            steps {
                echo "Build type selected: ${params.BUILD_TYPE}"
                sh "mvn package -P${params.BUILD_TYPE} -DskipTests"
            }
        }
    }

    post {
        success {
            echo 'Pipeline completed successfully!'
        }
        failure {
            echo 'Pipeline failed. Check the console output.'
        }
        always {
            echo 'Pipeline execution finished.'
        }
    }
}
